"""
Library Catalogue System

This module provides classes for Book, Member, and Loan to manage a library catalogue system.
Features include searching by author or title, overdue detection and fine calculation.
"""

from datetime import datetime, timedelta


class Book:
    """Class representing a book in the library."""

    def __init__(self, id_, title, author, year):
        """Initialize a book with ID, title, author, and publication year."""
        self.id = id_
        self.title = title
        self.author = author
        self.year = year
        self.is_available = True

    def __repr__(self):
        return f"<Book {self.id}: '{self.title}' by {self.author} ({self.year})>"


class Member:
    """Class representing a library member."""

    def __init__(self, id_, name):
        """Initialize a member with ID and name."""
        self.id = id_
        self.name = name
        self.loans = []

    def __repr__(self):
        return f"<Member {self.id}: {self.name}>"

    def borrow_book(self, book, loan_period_days):
        """Borrow a book if available and create a loan record."""
        if not book.is_available:
            raise Exception("Book not available for borrowing.")
        loan = Loan(book, self, datetime.now(), datetime.now() + timedelta(days=loan_period_days))
        self.loans.append(loan)
        book.is_available = False
        return loan

    def return_book(self, loan):
        """Return a book and mark the loan as completed."""
        if loan in self.loans and not loan.returned:
            loan.mark_returned(datetime.now())
            loan.book.is_available = True
        else:
            raise Exception("Invalid return or loan already returned.")


class Loan:
    """Class representing a book loan."""

    def __init__(self, book, member, start_date, due_date):
        self.book = book
        self.member = member
        self.start_date = start_date
        self.due_date = due_date
        self.returned = False
        self.return_date = None

    def mark_returned(self, return_date):
        self.returned = True
        self.return_date = return_date

    def is_overdue(self, current_date=None):
        if not current_date:
            current_date = datetime.now()
        return not self.returned and current_date > self.due_date

    def overdue_days(self, current_date=None):
        if not current_date:
            current_date = datetime.now()
        if self.is_overdue(current_date):
            delta = current_date - self.due_date
            return delta.days
        return 0

    def calculate_fine(self, fine_per_day, current_date=None):
        """Calculate fine based on overdue days and fine rate."""
        return self.overdue_days(current_date) * fine_per_day


class Catalogue:
    """Class representing the entire library catalogue system."""

    def __init__(self):
        self.books = []
        self.members = []

    def add_book(self, book):
        self.books.append(book)

    def add_member(self, member):
        self.members.append(member)

    def search_books_by_title(self, title):
        """Search for books matching the title substring (case insensitive)."""
        title_lower = title.lower()
        return [book for book in self.books if title_lower in book.title.lower()]

    def search_books_by_author(self, author):
        """Search for books matching the author substring (case insensitive)."""
        author_lower = author.lower()
        return [book for book in self.books if author_lower in book.author.lower()]

    def get_overdue_loans(self, current_date=None):
        """Return list of all overdue loans."""
        if not current_date:
            current_date = datetime.now()
        overdue_loans = []
        for member in self.members:
            for loan in member.loans:
                if loan.is_overdue(current_date):
                    overdue_loans.append(loan)
        return overdue_loans

    def calculate_total_fines(self, fine_per_day, current_date=None):
        """Calculate total fines for all members."""
        if not current_date:
            current_date = datetime.now()
        total = 0
        for member in self.members:
            for loan in member.loans:
                total += loan.calculate_fine(fine_per_day, current_date)
        return total


# End of catalogue.py
EOF

